    {regeneration&&<TerrainSourceWorkshop worldId={saved.worldId} api={api} relief={relief} regeneration={regeneration} onDirty={markOperationDirty} onClose={()=>{setRegeneration(undefined);markOperationDirty(false);}} onAccepted={(result,command)=>{if(command.action!=="save")return;if(result.reload){setRegeneration(undefined);markOperationDirty(false);onReload();return;}const patch={indices:[] as number[],before:[] as number[],after:[] as number[]},touched=new Set<number>();for(const tile of command.tiles){const k=tile.y*(shape.width/32)+tile.x;for(let n=0;n<1024;n++){const index=(tile.y*32+(n>>5))*shape.width+tile.x*32+(n&31);if(grid[index]!==tile.samples[n]){patch.indices.push(index);patch.before.push(grid[index]);patch.after.push(tile.samples[n]);grid[index]=tile.samples[n];touched.add(k);}}}if(patch.indices.length)push({patch,seaBefore:sea.current,seaAfter:sea.current});baseline.current.set(grid);revision.current=result.revision;baselineSea.current=sea.current;canvas.current?.refresh(touched);updateDirty(touched);didSave(result.revision);setAcceptedSource(command.source);setNotice(`Selected terrain accepted at revision ${result.revision}. Undo is available; all outside heights and map references were retained.`);setRegeneration(undefined);markTerrainDirty(false);}}/>}
