export function TerrainWorkspace({ worldId, review, ordinary, canEdit, onDirty }: { worldId: string; review: boolean; ordinary: boolean; canEdit: boolean; onDirty: (v: boolean) => void }) {
  const [bundle, setBundle] = useState<Bundle>(), [selected, setSelected] = useState(() => typeof window !== "undefined" ? new URL(window.location.href).searchParams.get("terrainMap") ?? "" : ""), [create, setCreate] = useState(false), [error, setError] = useState(""), [pending, setPending] = useState(true), [generation, setGeneration] = useState(0), localDirty = useRef(false);
  const cacheSource=useRef<Bundle|undefined>(undefined);
  const tileCache=useRef(new Map<string,{revision:number;tiles:TerrainDocument["tiles"];bytes:number}>());
  const [focusFrame,setFocusFrame]=useState<TerrainFrame>();
  const sourceDirty=useRef(false);const markSourceDirty=useCallback((value:boolean)=>{sourceDirty.current=value;onDirty(value||localDirty.current);},[onDirty]);
  const q = new URLSearchParams(); if (review) q.set("review", "1"); if (ordinary) q.set("ordinary", "1");
  const api = `/api/worlds/${worldId}/terrain${q.size ? `?${q}` : ""}`;
  useEffect(() => { if (ordinary) return; let alive = true; const controller = new AbortController(); const previous=cacheSource.current,sourceId=previous?.document?.terrainId,known=sourceId?tileCache.current.get(sourceId):undefined,cacheQuery=known?`&knownTerrain=${sourceId}&knownRevision=${known.revision}`:"";worldApi<Bundle>(`${api}${api.includes("?") ? "&" : "?"}${selected ? `terrainMap=${encodeURIComponent(selected)}` : ""}${cacheQuery}`, "GET", undefined, controller.signal).then(value => { if (alive) { const doc=value.document;if(doc){const cached=tileCache.current.get(doc.terrainId);if(doc.tilesUnchanged){if(!cached||cached.revision!==doc.revision)throw Error("Cached terrain expired. Retry loading its accepted source.");doc.tiles=cached.tiles;}else{const bytes=doc.tiles.reduce((sum,t)=>sum+t.samples.length*8+64,0);tileCache.current.delete(doc.terrainId);tileCache.current.set(doc.terrainId,{revision:doc.revision,tiles:doc.tiles,bytes});while([...tileCache.current.values()].reduce((sum,c)=>sum+c.bytes,0)>16*1024*1024)tileCache.current.delete(tileCache.current.keys().next().value!);}}cacheSource.current=value;setBundle(value); setError(""); } }).catch(failure => { if (alive){setBundle(current=>current?{...current,document:null}:current);setError(message(failure));} }).finally(() => { if (alive) setPending(false); }); return () => { alive = false; controller.abort(); }; }, [api, selected, ordinary, generation]);
  const dirtyChanged = useCallback((v: boolean) => { localDirty.current = v; onDirty(v||sourceDirty.current); }, [onDirty]);
  useEffect(() => () => onDirty(false), [onDirty]);
  function choose(id: string,frame?:TerrainFrame) { if ((localDirty.current||sourceDirty.current) && !window.confirm("Leave this terrain draft? Save or download it before switching maps.")) return; dirtyChanged(false);setFocusFrame(frame);setBundle(current=>current?{...current,document:null}:current); setPending(true); setSelected(id);if(id===selected)setGeneration(n=>n+1); const url = new URL(window.location.href); url.searchParams.delete("terrainDetail"); if (id) url.searchParams.set("terrainMap", id); else url.searchParams.delete("terrainMap"); window.history.replaceState(null, "", url.pathname + url.search); }
  if (ordinary) return <section className={styles.workspace}><h2>Atlas</h2><p>Terrain maps are creator material and are unavailable in ordinary-knowledge views.</p></section>;
  return <section className={styles.workspace} aria-label="Atlas"><header className={styles.heading}><div><h2>Atlas</h2><p>Shape the geography of {"this World"}. Begin with blank terrain, seeded geography or an imported heightmap, then sculpt and save it.</p></div>{canEdit && !review && <button className="st-button is-primary" disabled={pending} onClick={() => { if ((!localDirty.current&&!sourceDirty.current) || window.confirm("Leave the current terrain draft to create another map? Save or download it first.")) setCreate(true); }}>Create flat world</button>}</header>{error && <p role="alert" className={styles.feedback}>{error} <button className="st-button is-secondary" onClick={() => { setPending(true); setGeneration(n => n + 1); }}>Retry loading</button> <button className="st-button is-secondary" onClick={()=>choose("")}>Browse World maps</button></p>}{pending && <p role="status">Loading terrain…</p>}{bundle && <><GuidedField label="World terrain map" help="Choose a saved heightmap in this World. Independent World maps keep their terrain. Linked regions share their specific parent’s accepted geography." controlClassName="st-control"><select value={selected} disabled={pending} onChange={e => choose(e.target.value)}><option value="">Choose a map</option>{bundle.maps.filter(m=>!m.parentMapId).map(map=><optgroup key={map.id} label={map.name}><option value={map.id}>{map.name} · World</option>{bundle.maps.filter(m=>m.parentMapId===map.id).map(m=><option key={m.id} value={m.id}>{m.name} · Region</option>)}</optgroup>)}{bundle.maps.filter(m=>m.parentMapId&&!bundle.maps.some(p=>p.id===m.parentMapId)).map(m=><option key={m.id} value={m.id}>{m.name} · parent unavailable</option>)}</select></GuidedField>{!bundle.maps.length && <div className={styles.empty}><h3>Your geography begins here</h3><p>{canEdit ? "Create a flat world to start shaping mountains, valleys and shorelines." : "There are no heightmaps to review in this World."}</p></div>}{bundle.document && !pending && <Sculptor key={`${bundle.document.id}:${generation}`} document={bundle.document} maps={bundle.maps} initialFrame={focusFrame} onNavigate={choose} api={api} review={review} editable={canEdit && bundle.canEdit && !review} onDirty={dirtyChanged} onSaved={revision => setBundle(current => current ? { ...current, maps: current.maps.map(m => m.id === selected ? { ...m, revision } : m) } : current)} onReload={() => { dirtyChanged(false); setPending(true); setGeneration(n => n + 1); }}/>}</>}{create && <TerrainSourceWorkshop worldId={worldId} api={api} onDirty={markSourceDirty} onClose={()=>setCreate(false)} onAccepted={result=>{setCreate(false);markSourceDirty(false);choose(result.id);}}/>}</section>;
}
